// Builds the Sunday WhatsApp digest: who is due for follow-up, and whose birthday is coming up in the next 7 days.
function daysUntil(dateStr) {
  if (!dateStr) return null;
  const target = new Date(dateStr);
  if (isNaN(target.getTime())) return null;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  target.setHours(0, 0, 0, 0);
  return Math.round((target - today) / 86400000);
}

const items = $input.all();
const dueContacts = [];
const upcomingBirthdays = [];

for (const item of items) {
  const c = item.json;
  if ((c.status || 'Active') !== 'Active') continue;

  const followUpDays = daysUntil(c.next_follow_up_date);
  if (followUpDays !== null && followUpDays <= 0) {
    dueContacts.push(c);
  }

  const birthdayDays = daysUntil(c.next_birthday_date || c.birthday);
  if (birthdayDays !== null && birthdayDays >= 0 && birthdayDays <= 7) {
    upcomingBirthdays.push({ ...c, birthdayDays });
  }
}

let text = '👋 Sunday Network Check-in\n\n';

if (dueContacts.length > 0) {
  text += `Reach out to (${dueContacts.length}):\n`;
  dueContacts.forEach(c => {
    text += `\n• ${c.name}`;
    if (c.work) text += ` (${c.work})`;
    text += `\n  ${c.relationship_plan_note || 'Say hello and catch up.'}`;
  });
  text += '\n\n';
} else {
  text += 'No one is due for follow-up this week. 🎉\n\n';
}

if (upcomingBirthdays.length > 0) {
  text += 'Upcoming birthdays:\n';
  upcomingBirthdays.forEach(c => {
    text += `\n🎂 ${c.name} — in ${c.birthdayDays} day(s)`;
  });
}

return [{
  json: {
    digest_text: text.trim(),
    has_content: dueContacts.length > 0 || upcomingBirthdays.length > 0
  }
}];
